(r, big) => {
    const n = big ? 1000 : r.int(1, 9);
    const base = r.int(0, 3);
    const nodes = [], open = [];
    const make = () => ({ v: r.bool(big ? 0.9995 : 0.85) ? base : r.int(0, 3), l: null, r: null });
    const root = make();
    nodes.push(root); open.push(root);
    for (let i = 1; i < n; i++) {
      const k = r.int(0, open.length - 1), p = open[k], c = make();
      if (!p.l && (p.r || r.bool())) p.l = c; else p.r = c;
      if (p.l && p.r) { open[k] = open[open.length - 1]; open.pop(); }
      open.push(c);
    }
    const out = [], q = [root];
    for (let i = 0; i < q.length; i++) {
      const node = q[i];
      if (!node) { out.push(null); continue; }
      out.push(node.v);
      q.push(node.l, node.r);
    }
    while (out.length && out[out.length - 1] === null) out.pop();
    return [out];
  }

